import jDialog from '@/component/dialog.vue';
export default {
	props: {
		
		// 是否显示弹窗
		isShowDialog: {
			type: Boolean,
			required: true,
			default() {
				return false;
			}
		},
	},
	data() {
		return {
			userpwd: '',
			newPwd: '',
			userConfirmPwd: '',
			pwdType: 'password',
			isSubmiting: false
		};
	},
	created() {},
	methods: {
		// 输入密码
		inputPwd(e) {
			this.userpwd = e.target.value;
		},
		// 新密码
		inputNewPwd(e) {
			this.newPwd = e.target.value;
		},
		// 确认密码
		inputConfirmPwd(e) {
			this.userConfirmPwd = e.target.value;
		},
		// 查看密码
		switchPwd() {
			this.pwdType = this.pwdType === 'text' ? 'password' : 'text';
		},
		// 注册
		changePwdEvt() {
			if(this.isSubmiting){
				return
			}
			const userpwd = this.userpwd,
				newPwd = this.newPwd,
				userConfirmPwd = this.userConfirmPwd;
			if (!userpwd.trim()) {
				this.$common.toast('请输入密码');
				return;
			}
			if (!newPwd.trim()) {
				this.$common.toast('请输入新密码');
				return;
			}
			if (!userConfirmPwd.trim()) {
				this.$common.toast('请输入确认密码');
				return;
			}
			if (userConfirmPwd.trim() !== newPwd.trim()) {
				this.$common.toast('两次密码输入不一致');
				return;
			}
			const params = {
				newPwd: newPwd,
				password: userpwd
			};
			this.isSubmiting = true;
			this.$api({
				url: '/user/changePwd',
				data: params
			})
				.then(res => {
					this.closeDialog();
					this.$emit('changePwdSuccess', true);
				})
				.catch(e => {
					this.$common.toast(e.msg);
				})
				.finally(() => {
					this.isSubmiting = false;
				});
		},

		closeDialog() {
			this.userpwd = '';
			this.newPwd = '';
			this.userConfirmPwd = '';
			this.$emit('closeDialog', false);
		}
	},
	components: { jDialog }
};
